'use strict';

module.exports = function() {

  // raster images: compressed with sharp
  function rasterImages() {
    return $.gulp.src('./src/img/**/*.{png,jpg,jpeg,gif,webp}', { encoding: false })
      .pipe($.gp.newer($.config.root + '/assets/img'))
      .pipe($.sharpOptimizeImages({
        jpg_to_jpg: { quality: 80, mozjpeg: true },
        png_to_png: { quality: 80, compressionLevel: 9 }
      }))
      .pipe($.gulp.dest($.config.root + '/assets/img'));
  }

  // svg images: minified with svgo
  function svgImages() {
    return $.gulp.src('./src/img/**/*.svg')
      .pipe($.gp.newer($.config.root + '/assets/img'))
      .pipe($.gp.svgmin({ plugins: [{ name: 'removeViewBox', active: false }] }))
      .pipe($.gulp.dest($.config.root + '/assets/img'));
  }

  $.gulp.task('image:min', $.gulp.parallel(rasterImages, svgImages));

};
